import{_ as d,C as o,o as c,c as l,a6 as n,E as t,j as s,a}from"./chunks/framework.5dd0l9Wo.js";const q=JSON.parse('{"title":"NoSQL Injection","description":"MongoDB operator injection, authentication bypass, regex extraction, and unknown-field enumeration.","frontmatter":{"title":"NoSQL Injection","description":"MongoDB operator injection, authentication bypass, regex extraction, and unknown-field enumeration."},"headers":[],"relativePath":"nosql-injection/index.md","filePath":"nosql-injection/index.md"}'),h={name:"nosql-injection/index.md"};function p(u,e,k,g,m,y){const i=o("LabGroup"),r=o("TopicComplete");return c(),l("div",null,[e[0]||(e[0]=n('<h1 id="nosql-injection" tabindex="-1">NoSQL Injection <a class="header-anchor" href="#nosql-injection" aria-label="Permalink to &quot;NoSQL Injection&quot;">​</a></h1><p class="wd-section-lede">NoSQL does not remove injection; it changes the grammar. Instead of SQL keywords, the attacker abuses query operators and the way a JSON body is converted into a query document.</p><div class="wd-callout"><p><strong>The model.</strong> A MongoDB query is a document: <code>{ username: &quot;alice&quot;, password: &quot;...&quot; }</code>. If the application copies user-controlled JSON into that document, the user can supply an <em>object</em> where a string was expected — and that object can contain operators such as <code>$ne</code>, <code>$regex</code>, or <code>$where</code>.</p></div><h2 id="operator-injection" tabindex="-1">Operator injection <a class="header-anchor" href="#operator-injection" aria-label="Permalink to &quot;Operator injection&quot;">​</a></h2><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;username&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;$ne&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">null</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;password&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;$ne&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">null</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>The query becomes &quot;find a document whose username is not null and whose password is not null&quot; — the first user in the collection. The password check is gone, not because it was bypassed, but because the operator changed the predicate.</p><details class="details custom-block"><summary>🔬 Under the Hood: string vs object types in a query</summary><p>MongoDB is type-sensitive. <code>{ username: &quot;admin&quot; }</code> matches a string. <code>{ username: { $ne: null } }</code> matches any value not equal to null. If the server does <code>users.findOne({ username: req.body.username, password: req.body.password })</code>, an object in either field is passed through as an operator expression.</p><p>Express&#39;s <code>body-parser</code> with <code>extended: true</code> (or <code>qs</code>) also creates nested objects from bracket syntax, so a form-encoded body can produce the same structure without JSON.</p></details><h2 id="detection-and-authentication-bypass" tabindex="-1">Detection and authentication bypass <a class="header-anchor" href="#detection-and-authentication-bypass" aria-label="Permalink to &quot;Detection and authentication bypass&quot;">​</a></h2><p>Start with a harmless operator that changes behaviour: <code>$ne</code>, <code>$gt</code>, <code>$regex</code>. A login that succeeds with <code>{&quot;$ne&quot;: null}</code> proves the input reaches the query untyped.</p>',9)),t(i,{ids:"nosql-injection-lab-nosql-injection-detection, nosql-injection-lab-nosql-injection-bypass-authentication"}),e[1]||(e[1]=n('<h2 id="extracting-data-with-regex" tabindex="-1">Extracting data with regex <a class="header-anchor" href="#extracting-data-with-regex" aria-label="Permalink to &quot;Extracting data with regex&quot;">​</a></h2><p>When the response is boolean (login succeeds or fails), use <code>$regex</code> as an oracle. Test one character at a time against a known field.</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;username&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;admin&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;password&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;$regex&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;^a&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>A match authenticates; a miss does not. This is blind SQL injection with a different operator set.</p>',4)),t(i,{ids:"nosql-injection-lab-nosql-injection-extract-data"}),e[2]||(e[2]=s("h2",{id:"unknown-fields-and-where",tabindex:"-1"},[a("Unknown fields and "),s("code",null,"$where"),a(),s("a",{class:"header-anchor",href:"#unknown-fields-and-where","aria-label":'Permalink to "Unknown fields and `$where`"'},"​")],-1)),e[3]||(e[3]=s("p",null,[a("If the field names are unknown, "),s("code",null,"$where"),a(" executes JavaScript per document. Timing or error differences can reveal field names and values. In MongoDB, "),s("code",null,"$where"),a(" is disabled in many managed offerings but remains a classic primitive.")],-1)),t(i,{ids:"nosql-injection-lab-nosql-injection-extract-unknown-fields"}),e[4]||(e[4]=n('<details class="details custom-block"><summary>⚙️ Engine Variations: query semantics</summary><ul><li><strong>MongoDB:</strong> operator injection, <code>$where</code> JavaScript, <code>$lookup</code> aggregation joins. <code>$regex</code> is case-sensitive unless <code>$options: &quot;i&quot;</code>.</li><li><strong>CouchDB:</strong> <code>_all_docs</code> and view queries; injection through <code>startkey</code>/<code>endkey</code> JSON.</li><li><strong>Redis:</strong> command injection through unsanitised key names; <code>EVAL</code> is a code-execution surface.</li><li><strong>Elasticsearch:</strong> query DSL injection, script fields, and <code>_search</code> template injection.</li><li><strong>Firebase/Firestore:</strong> security rules are the authorisation layer; client SDK queries are not.</li></ul><p>The common thread is a query language with operators and no parameterisation boundary.</p></details><div class="wd-callout wd-callout--warn"><p><strong>Defence.</strong> Cast every field to its expected type before it reaches the query (<code>typeof username === &#39;string&#39;</code>). Use schema validation (Mongoose, JSON Schema, Zod). Never pass a request body directly as a query filter. Disable <code>$where</code> and JavaScript execution in the database. Apply least-privilege database users.</p></div>',2)),t(r,{"topic-id":"nosql-injection",label:"Mark NoSQL injection complete"})])}const E=d(h,[["render",p]]);export{q as __pageData,E as default};
